_LIVE_RENDER = r"""function renderRich(entries){const threads=latestThreads(entries),records=conversationAgentRecords(threads);if(!threads.length&&!records.length)return false;panel.replaceChildren();const focused=conversationFocusRecord(records);if(focused){renderFocusedConversation(panel,focused);return true}const ordered=orderedConversationRecords(records),count=ordered.reduce((n,record)=>n+conversationMessageCount(record),0),summary=document.createElement('div');summary.className='conversation-live-summary';summary.textContent=`${ordered.length} agent${ordered.length===1?'':'s'} · ${count} visible item${count===1?'':'s'} · provider-neutral run-local record · each agent shows only its own conversation`;panel.appendChild(summary);if(!conversationRootRecord(records)){const notice=document.createElement('div');notice.className='conversation-live-unresolved-root';notice.textContent='No root agent identified in this run’s evidence. Agent conversations are listed without a parent.';panel.appendChild(notice)}const list=document.createElement('div');list.className='execweave-conversation-agent-list';for(const record of ordered)list.appendChild(conversationAgentSection(record));panel.appendChild(list);const index=document.createElement('a');index.className='conversation-live-index';index.href=`/conversations.md${window.__execweaveToken?`?t=${encodeURIComponent(window.__execweaveToken)}`:''}`;index.target='_blank';index.rel='noreferrer';index.textContent='Open complete conversation index';panel.appendChild(index);return true}""".strip()


def _replace_between(html: str, start: str, following: str, replacement: str) -> str:
    begin = html.find(start)
    if begin < 0:
        return html
    end = html.find(following, begin)
    if end < 0:
        return html
    return html[:begin] + replacement + "\n" + html[end:]


def _neutralize_copy(html: str) -> str:
    return (
        html.replace(
            "Provider-encrypted payload — plaintext is not exposed by the Codex rollout.",
            "Provider-encrypted payload — plaintext is not exposed by the observed provider surface.",
        )
        .replace("Open run-local raw rollout evidence", "Open raw conversation evidence")
        .replace("Open raw rollout evidence", "Open raw conversation evidence")
        .replace("Codex conversation", "Conversation")
    )


def inject_standalone_conversation_tree(html: str) -> str:
    """Render provider-neutral run-local conversations as a rooted agent hierarchy."""
    html = _neutralize_copy(html)
    if "function execweaveRenderRichConversationRecords(panel,entries){" not in html:
        return html
    result = html.replace("</style>", _TREE_CSS + "\n</style>", 1)
    marker = "function execweaveRenderRichConversationRecords(panel,entries){"
    result = result.replace(marker, _STATIC_HELPERS + "\n" + marker, 1)
    return _replace_between(
        result,
        marker,
        "function execweaveRenderConversationRecords(){",
        _STATIC_RENDER,
    )


def inject_live_conversation_tree(html: str) -> str:
    """Give the live conversation panel the same provider-neutral hierarchy."""
    html = _neutralize_copy(html)
    if "function renderRich(entries){" not in html:
        return html
    result = html.replace("</style>", _TREE_CSS + "\n</style>", 1)
    marker = "function renderRich(entries){"
    result = result.replace(marker, _LIVE_HELPERS + "\n" + marker, 1)
    return _replace_between(result, marker, "async function loadIndex(){", _LIVE_RENDER)
